import assert from "node:assert/strict";
import { SearchDriver } from "./runtime/sources/common/src/simulation/search_driver";
import { getA19NeuralState } from "./runtime/sources/common/src/simulation/a19_neural";
import { GameActionEngine } from "./runtime/sources/common/src/engine/action_engine";

const clone = (x: any) => JSON.parse(JSON.stringify(x));
const key = (x: any) => JSON.stringify(x);
let mode = "off", team = 0, frame: any = null, sample: any = null;
let observations: any[] = [];
let usedCorrection = false;
export function configure(m: string, t: number) { mode = m; team = t; frame = null; sample = null; observations = []; usedCorrection = false; }
export const collected = () => ({ observations });
function material(d: any, u: any) {
    let own = 0, enemy = 0;
    for (const v of d.unitsHolder.getAllUnits().values()) {
        if (v.isDead()) continue;
        const xp = v.getExp() * v.getCumulativeHp() / Math.max(1, v.getMaxHp());
        if (v.getTeam() === u.getTeam()) own += xp; else enemy += xp;
    }
    return { own, enemy, actorHp: u.isDead() ? 0 : u.getCumulativeHp() };
}
function shots(actions: any[]) { return actions.some(a => a.type === "range_attack"); }
const sp = SearchDriver.prototype as any, applies = sp.appliesTo, score = sp.scoreCandidates,
    rollout = sp.rollout, finals = new WeakMap<any, any>();
function choose(this: any, unit: any, version: any, incumbent: any, context: any) {
    const prior = frame;
    frame = mode !== "off" && unit.getTeam() === team ? {
        driver: this, unit, actor: { id: unit.getId(), name: unit.getName(), hp: unit.getCumulativeHp() },
        lap: this.deps.fightProperties.getCurrentLap(), samples: [], scores: [],
    } : null;
    const f = frame;
    try {
        const chosen = finals.get(this).call(this, unit, version, incumbent, context);
        if (!f) return chosen;
        const finalScores = f.scores.filter((s: any) => s.mode === "turns").at(-1);
        const candidates = finalScores?.candidates ?? [];
        const index = candidates.findIndex((c: any) => key(c.actions) === key(chosen));
        const rows = (k: string) => f.samples.filter((s: any) => s.mode === "turns" && s.key === k && s.after && Number.isFinite(s.value));
        const confirmed = (r: any[]) => r.length === 2 && new Set(r.map(x => x.repeat)).size === 2;
        const losing = (s: any) => s.after.actorHp <= 0 && s.ownLost > 0 && s.enemyLost < s.ownLost * 0.25;
        const source = index >= 0 ? rows(key(chosen)) : [];
        const danger = shots(chosen) && confirmed(source) && source.every(losing);
        let alternative: any = null;
        if (danger && Number.isFinite(finalScores.means[index])) {
            const options = candidates.map((c: any, i: number) => ({ c, i, mean: finalScores.means[i], samples: rows(key(c.actions)) }))
                .filter((o: any) => o.i !== index && shots(o.c.actions) && Number.isFinite(o.mean) &&
                    confirmed(o.samples) &&
                    o.samples.every((s: any) => s.after.actorHp > 0 && s.enemyLost > 0 && s.ownLost <= s.enemyLost))
                .map((o: any) => ({ ...o, net: o.samples.reduce((n: number, s: any) => n + s.enemyLost - s.ownLost, 0) / 2 }))
                .sort((a: any, b: any) => b.mean - a.mean || b.net - a.net || a.i - b.i);
            alternative = options[0] ?? null;
        }
        const correction = mode === "candidate" && !usedCorrection && alternative;
        const replacement = correction ? alternative.c.actions : chosen;
        if (correction) usedCorrection = true;
        if (shots(chosen) || danger || alternative) observations.push({
            actor: f.actor, lap: f.lap, chosen: clone(chosen), finalChosen: clone(replacement), danger,
            alternative: alternative ? clone(alternative) : null, changed: key(chosen) !== key(replacement),
            scores: f.scores, samples: f.samples,
        });
        return replacement;
    } finally { frame = prior; }
}
sp.appliesTo = function (...args: any[]) {
    if (getA19NeuralState(this) && !finals.has(this)) {
        finals.set(this, this.chooseDecision);
        Object.defineProperty(this, "chooseDecision", { value: choose, writable: true, configurable: true });
    }
    return applies.apply(this, args);
};
sp.scoreCandidates = function (...args: any[]) {
    const values = score.apply(this, args);
    if (frame?.driver === this) frame.scores.push({ mode: args[3], candidates: clone(args[1]), means: values.map((v: number) => Number.isFinite(v) ? v : null) });
    return values;
};
sp.rollout = function (u: any, c: any, seed: any, repeat: any, horizon: any, ...args: any[]) {
    const prior = sample;
    sample = frame?.driver === this && shots(c.actions) ? {
        driver: this, unit: u, actions: c.actions, next: 0, key: key(c.actions), mode: horizon, seed, repeat,
        before: material(this.deps, u), after: null,
    } : null;
    const s = sample;
    try {
        const value = rollout.call(this, u, c, seed, repeat, horizon, ...args);
        if (s) {
            const { driver, unit, actions, next, ...row } = s;
            frame.samples.push({ ...row, value: Number.isFinite(value) ? value : null });
        }
        return value;
    } finally { sample = prior; }
};
const ep = GameActionEngine.prototype as any, apply = ep.apply;
ep.apply = function (action: any) {
    const s = sample, root = s && !s.after && action === s.actions[s.next];
    const result = apply.call(this, action);
    if (root) {
        s.next++;
        if (s.next === s.actions.length) {
            s.after = material(s.driver.deps, s.unit);
            s.ownLost = s.before.own - s.after.own;
            s.enemyLost = s.before.enemy - s.after.enemy;
        }
    }
    return result;
};

