import assert from "node:assert/strict";
import { readFileSync, statfsSync } from "node:fs";
import { join } from "node:path";
import { draft, actualOpening } from "./runtime/opening";
import { play } from "./runtime/play";
import { assertPackageIdentity } from "./runtime/identity";
import { configure, collected } from "./hooks";
import { P, read, save, sha, digest } from "./io";
const reg = read("registration.json");
for (const [file, hash] of Object.entries(reg.hashes)) assert.equal(sha(readFileSync(join(P, file))), hash, file);
assertPackageIdentity();
const [host, workerText, workersText, stage = "pilot"] = process.argv.slice(2), worker = Number(workerText), workers = Number(workersText);
assert(["local", "hft"].includes(host));
const families = read("cases.json");
const jobs = families.flatMap((task: any, index: number) => [0, 1].flatMap(seat => [0, 1].map(future => ({ task, index, seat, future, id: `${task.id}-s${seat}-f${future}` }))));
const selected = stage === "cold" ? jobs.filter((x: any) => [0, 36, 72].includes(x.index) && x.seat === 0 && x.future === 0) : jobs;
for (let j = worker; j < selected.length; j += workers) {
    const job = selected[j];
    const rows: any = {};
    for (const mode of (job.index + job.seat + job.future) % 2 ? ["candidate", "observe"] : ["observe", "candidate"]) {
        assert(Date.now() < reg.cutoffUnix * 1000, "Fixed study cutoff");
        const fs = statfsSync(P); assert(fs.bavail * fs.bsize > 2 * 1024 ** 3);
        configure("off", 0);
        const opening = actualOpening(draft(job.task), job.seat ? job.task.reverseSetup : job.task.setup, !!job.seat);
        configure(mode, opening.candidateTeam);
        const result = play(opening, job.task.evalFutures[job.future]);
        assert(result.qualityPassed, result.error);
        const row = { ...result, opening, ...collected(), job, host, mode, registrationSha256: sha(readFileSync(join(P, "registration.json"))) };
        save(`${stage}/${job.id}-${mode}.json.gz`, row);
        rows[mode] = row;
        if (stage === "cold") {
            const prior = read(`pilot/${job.id}-${mode}.json.gz`);
            for (const field of ["opening", "result", "turns", "events", "health", "observations"]) assert.equal(digest(row[field]), digest(prior[field]), field);
        }
    }
    assert.equal(digest(rows.observe.opening), digest(rows.candidate.opening));
    save(`${stage}/complete-${job.id}.json`, { qualityPassed: true, job, host });
    console.log(JSON.stringify({ stage, host, worker, completed: job.id }));
}

