import assert from "node:assert/strict";
import { draft, actualOpening } from "./runtime/opening";
import { play } from "./runtime/play";
import { configure, collected } from "./hooks";
import { read, save, digest } from "./io";
const worker = Number(process.argv[2] ?? 0), workers = Number(process.argv[3] ?? 1), host = process.argv[4] ?? "local";
const jobs = read("admission-fixtures/branches.json");
const indices = host === "hft" ? [0, 6, 13] : jobs.map((_j: any, i: number) => i);
for (let index = worker; index < indices.length; index += workers) {
    const job = jobs[indices[index]], expected = read(`admission-fixtures/${job.id}.json.gz`);
    configure("off", 0);
    const opening = actualOpening(draft(job.task), job.seat ? job.task.reverseSetup : job.task.setup, !!job.seat);
    configure("candidate", opening.candidateTeam);
    const result = play(opening, job.task.evalFutures[job.future]);
    assert(result.qualityPassed, result.error);
    assert.equal(collected().observations.filter(o => o.changed).length, 1);
    for (const field of ["result", "turns", "events", "health"]) assert.equal(digest(result[field]), digest(expected[field]), field);
    assert.equal(digest(opening), digest(expected.opening));
    save(`admission-${host}/${job.id}.json`, { qualityPassed: true, exactlyOneCorrection: true, originalForcedTraceMatched: true, openingHash: digest(opening), turnHash: digest(result.turns), healthHash: digest(result.health) });
    console.log(JSON.stringify({ completed: job.id, host, exactlyOneCorrection: true }));
}

