import assert from "node:assert/strict";
import { draft } from "./runtime/opening";
import { creatureInfo, creatureIdForName } from "./runtime/sources/common/src/ai/setup/creature_score";
import { read, save } from "./io";
const counts = new Map<string, number>(), selected: any[] = [], examined: any[] = [];
for (const task of read("manifest.json").pool) {
    const stratum = `${task.map}/${task.d1}/${task.d2}/${task.pickOrder}`;
    if ((counts.get(stratum) ?? 0) >= 2) continue;
    const d = draft(task);
    const armed = [d.config.roster, d.config.redRoster].map(r => r.some((u: any) => creatureInfo(creatureIdForName(u.creatureName)!)?.ranged));
    examined.push({ id: task.id, armed });
    if (armed.every(Boolean)) { counts.set(stratum, (counts.get(stratum) ?? 0) + 1); selected.push(task); }
}
assert.equal(selected.length, 108);
save("cases.json", selected);
save("selection.json", { rule: "First two natural drafts with a ranged unit on both teams per map/doctrine pair/pick order", families: selected.length, examined, noCombatOutcomesOpened: true });
console.log(JSON.stringify({ families: selected.length, examined: examined.length }));

