import assert from "node:assert/strict";
import { read, save } from "./io";
const summary = read("analysis.json"), families = read("cases.json"), sums: number[] = [];
let better = 0, worse = 0, tied = 0;
for (const family of families) {
    let delta = 0;
    for (const seat of [0, 1]) for (const future of [0, 1]) {
        const score = (mode: string) => {
            const r = read(`pilot/${family.id}-s${seat}-f${future}-${mode}.json.gz`);
            assert(r.qualityPassed && r.receipt.qualityPassed);
            return r.result.winner === "draw" ? 1 : r.result.winner === (r.candidateTeam === 2 ? "green" : "red") ? 2 : 0;
        };
        const d = score("candidate") - score("observe");
        delta += d;
        if (d > 0) better++; else if (d < 0) worse++; else tied++;
    }
    sums.push(delta);
}
const mean = sums.reduce((a, b) => a + b, 0) / (8 * sums.length) * 100;
let state = 17112026;
function next() { state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return state >>> 0; }
const resamples: number[] = [];
for (let b = 0; b < 20000; b++) {
    let value = 0;
    for (let i = 0; i < sums.length; i++) value += sums[next() % sums.length];
    resamples.push(value / (8 * sums.length) * 100);
}
resamples.sort((a, b) => a - b);
const interval = [resamples[500], resamples[19500]];
assert(Math.abs(mean - summary.meanScoreGainPp) < 1e-12);
interval.forEach((x, i) => assert(Math.abs(x - summary.familyBootstrap95Pp[i]) < 1e-12));
assert.equal(better, summary.counters.better_cases ?? 0);
assert.equal(worse, summary.counters.worse_cases ?? 0);
assert.equal(tied, summary.counters.tied_cases ?? 0);
const proof = { qualityPassed: true, independentIntegerHalfPointReconstruction: true, families: sums.length, better, worse, tied, meanPp: mean, intervalPp: interval, priorVerifierRepair: "Python Counter omits zero-valued better/worse keys; normalize absent counters to zero. No input, policy or result changed." };
save("independent-verification.json", proof);
console.log(JSON.stringify(proof));
